function security(){return `${heading('Acceso y contraseña','Actualiza la contraseña de este administrador desde el panel.')}<section class="dashboard-card auth-settings-card"><div class="dash-card-title"><div><h2>Credenciales del administrador</h2><p>Tu cuenta personal está administrada por Supabase Auth.</p></div><span class="state-pill open">● Sesión iniciada</span></div><form id="changePasswordForm" autocomplete="off"><div class="auth-form-grid"><label class="form-label">Contraseña actual<input type="password" name="currentPassword" autocomplete="current-password" required></label><label class="form-label">Nueva contraseña<input type="password" name="newPassword" autocomplete="new-password" minlength="12" maxlength="128" required></label><label class="form-label">Confirmar nueva contraseña<input type="password" name="repeatPassword" autocomplete="new-password" minlength="12" maxlength="128" required></label></div><label class="show-pass"><input type="checkbox" id="toggleSecurityPasswords"> Mostrar contraseñas</label><p class="setting-desc">Usa al menos 12 caracteres e incluye mayúsculas, minúsculas, números y un símbolo.</p><p id="passwordFeedback" class="auth-feedback" role="status" aria-live="polite" hidden></p><div class="form-foot"><span>La nueva contraseña será válida para tu cuenta de Supabase en todos los dispositivos.</span><button type="submit" class="admin-primary">Guardar nueva contraseña</button></div></form></section><div class="demo-alert admin-info"><b>Importante:</b> el acceso y las políticas de permisos se validan en Supabase. No incluyas claves secretas de servicio en los archivos públicos.</div>`}
function innerContent(){return ({dashboard,eventos,enrollment,programs:()=>records('programs'),news:()=>records('news'),gallery:()=>records('gallery'),staffYears:()=>records('staffYears'),offers:()=>records('offers'),analytics,teachers:()=>records('teachers'),directors:()=>records('directors'),historyGallery:()=>records('historyGallery'),achievements:()=>records('achievements'),partners:()=>records('partners'),projects:()=>records('projects'),calendarEvents:()=>records('calendarEvents'),alumni:()=>records('alumni'),tours:()=>records('tours'),faqs:()=>records('faqs'),documents:()=>records('documents'),jobs:()=>records('jobs'),messages,settings,security})[section]?.()||dashboard()}
function formField([key,label,type],r){const val=r?.[key]??'';
 if(type==='specialty')return `<label class="form-label">${e(label)}<select name="${e(key)}" required>${STAFF_SPECIALTIES.map(x=>`<option value="${e(x)}" ${val===x?'selected':''}>${e(x)}</option>`).join('')}</select></label>`;
 if(type==='check')return `<label class="checkbox-field"><input name="${e(key)}" type="checkbox" ${r?val?'checked':'':'checked'}><span>${e(label)}</span></label>`;
 if(type==='textarea')return `<label class="form-label">${e(label)}<textarea name="${e(key)}" rows="4">${e(val)}</textarea></label>`;
 if(type==='image')return `<label class="form-label">${e(label)}<select name="${e(key)}"><option value="${e(val)}">${r?'Conservar actual':'Elegir imagen de muestra'}</option>${images.map(i=>`<option value="${e(i)}">${e(imageLabel(i)||i)}</option>`).join('')}</select><small>O carga una imagen (PNG, JPG, WEBP)</small><input type="file" accept="image/png,image/jpeg,image/webp" name="upload_${e(key)}"><small>Imágenes de hasta 8 MB de entrada; se optimizan y suben a Supabase Storage.</small></label>`;
 if(type==='pdf')return `<label class="form-label">${e(label)}<input type="url" name="${e(key)}" placeholder="https://.../documento.pdf" value="${val.startsWith('data:')?'':e(val)}"><small>Puedes colocar un enlace HTTPS a un PDF o adjuntar uno pequeño:</small><input name="upload_${e(key)}" type="file" accept="application/pdf"><small>Máximo 5 MB por PDF. ${val.startsWith('data:')?'PDF local actual adjunto.':''}</small></label>`;
 return `<label class="form-label">${e(label)}<input type="${type==='date'?'date':'text'}" name="${e(key)}" ${['title','category'].includes(key)?'required':''} value="${e(val||'')}" maxlength="1200"></label>`;}
function openModal(markup){document.querySelector('#adminModalBody').innerHTML=markup;document.querySelector('#adminModal').hidden=false;document.body.style.overflow='hidden';document.querySelectorAll('[data-dismiss]').forEach(b=>b.addEventListener('click',closeModal));document.querySelector('[data-dismiss]')?.focus();}
function closeModal(){const modal=document.querySelector('#adminModal');if(modal)modal.hidden=true;document.body.style.overflow='';}
function recordModal(key,id){if(['programs','offers'].includes(key)&&!id){toast('Edita las cuatro especialidades existentes.');return;}const conf=schema[key],r=db[key].find(r=>r.id===id);openModal(`<div class="modal-eyebrow">ADMINISTRACIÓN DE CONTENIDOS</div><h2>${r?'Editar':'Agregar'} ${e(conf.name)}</h2><p>Esta información podrá mostrarse en la página pública.</p><form id="recordForm" data-table="${key}" data-id="${e(id||'')}"><div class="record-form-fields">${conf.fields.map(field=>formField(field,r)).join('')}</div><div class="modal-actions"><button class="admin-outlined" type="button" data-dismiss>Cancelar</button><button type="submit" class="admin-primary">${r?'Guardar cambios':'Crear publicación'}</button></div></form>`)}
const fileToData=async(file,type)=>{
 const accepted=type==='pdf'?['application/pdf']:['image/png','image/jpeg','image/webp'];
 if(!accepted.includes(file.type))throw Error('El formato debe ser JPG, PNG, WEBP o PDF según corresponda.');
 const readOriginal=()=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(Error('No se pudo leer el archivo.'));r.readAsDataURL(file)});
 if(type==='pdf')return window.CETPRO_CLOUD.uploadFile(file,'pdf');
 if(file.size<=450*1024)return window.CETPRO_CLOUD.uploadFile(file,'image');
 if(file.size>8*1024*1024)throw Error('La imagen debe pesar 8 MB o menos.');
 const url=URL.createObjectURL(file);
 try{
  const source=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('La imagen no se puede leer.'));img.src=url;});
  let scale=Math.min(1,1200/Math.max(source.naturalWidth,source.naturalHeight));let result='';
  for(let i=0;i<5;i++){
   const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.naturalWidth*scale));canvas.height=Math.max(1,Math.round(source.naturalHeight*scale));
   const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0,canvas.width,canvas.height);
   result=canvas.toDataURL('image/jpeg',Math.max(.5,.8-i*.07));
   if(result.length<550000)return window.CETPRO_CLOUD.uploadDataURL(result,'image');
   scale*=.77;
  }
  throw Error('No se pudo optimizar la foto. Intenta usar una imagen más pequeña.');
 }finally{URL.revokeObjectURL(url);}
};
async function saveForm(evt){evt.preventDefault();const f=evt.target,key=f.dataset.table,id=f.dataset.id,z=schema[key];if(!z)return;
 const fd=new FormData(f),old=db[key].find(x=>x.id===id)||{},record={...old,id:id||uid(key.slice(0,1))};
 for(const [field,_,type] of z.fields){const up=fd.get('upload_'+field);if(up instanceof File&&up.size){try{record[field]=await fileToData(up,type)}catch(err){toast(err.message);return}}
 else if(type==='check')record[field]=fd.has(field);
 else if(type==='pdf')record[field]=String(fd.get(field)||'').trim()||old[field]||'';
 else if(type==='image')record[field]=String(fd.get(field)||'').trim()||old[field]||'ilustracion-campus.svg';
 else record[field]=String(fd.get(field)||'').trim();}
 if(['teachers','directors'].includes(key)){
   const years=String(record.years||'').split(',').map(x=>x.trim()).filter(Boolean);
   if(!years.length||years.some(y=>!/^20\d{2}$/.test(y))){toast('Ingresa años válidos separados por comas, por ejemplo: 2026, 2027.');return;}
   record.years=[...new Set(years)].sort((a,b)=>Number(b)-Number(a)).join(', ');
   if(key==='teachers'&&!STAFF_SPECIALTIES.includes(record.specialty)){toast('Elige una de las cuatro especialidades del CETPRO.');return;}
 }
 if(['staffYears','historyGallery','achievements','partners'].includes(key) && !/^20\d{2}$/.test(String(record.year||''))){toast('Coloca un año académico válido de cuatro dígitos.');return;}
 if(key==='staffYears'&&db.staffYears.some(x=>x.id!==record.id&&String(x.year)===String(record.year))){toast('Ya existe una fotografía grupal para ese año. Edítala en lugar de duplicarla.');return;}
 if(['teachers','directors','historyGallery','alumni','projects','tours'].includes(key))record.demo=false;
 if(key==='offers'){
  const fixed=db.offers.find(x=>x.id===id);if(!fixed){toast('Especialidad no disponible');return;}
  record.programId=fixed.programId;record.title=db.programs.find(x=>x.id===fixed.programId)?.title||fixed.title;
  if(record.vacancies!==''&&(!/^\d+$/.test(record.vacancies)||Number(record.vacancies)<0)){toast('Las vacantes deben ser un número entero mayor o igual que cero.');return;}
  if(record.start&&record.end&&record.start>record.end){toast('La fecha final debe ser posterior al inicio.');return;}
 }
 if(['projects','alumni'].includes(key)&&record.year&&!/^20\d{2}$/.test(record.year)){toast('Utiliza un año válido, por ejemplo 2026.');return;}
 if(['projects','tours'].includes(key)&&record.video&&!/^https:\/\//i.test(record.video)){toast('El video debe tener una dirección HTTPS.');return;}
 if(!record.title?.trim()){toast('Completa el título.');return;}if(['programs','offers'].includes(key)&&!id){toast('Solo se permiten las cuatro especialidades actuales.');return;}const prev=[...db[key]];db[key]=id?db[key].map(x=>x.id===id?record:x):[record,...db[key]];
 if(persist('Publicación guardada correctamente.')){closeModal();render();}else db[key]=prev;}
function csvExport(){const head=['Fecha','Nombre','DNI','Celular','Correo','Especialidad','Convocatoria','Estado','Observaciones'];const cells=db.enrollments.map(x=>[x.createdAt,x.full_name,x.dni,x.phone,x.email,programName(x.programId),x.cycle,x.status,x.notes]);const quote=x=>'"'+String(x??'').replace(/"/g,'""').replace(/^[=+\-@]/,'\'$&')+'"';const csv='\uFEFF'+[head,...cells].map(row=>row.map(quote).join(';')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='solicitudes_cetpro.csv';a.click();URL.revokeObjectURL(url)}
function enrollmentDetails(x){openModal(`<div class="modal-eyebrow">SOLICITUD RECIBIDA</div><h2>${e(x.full_name)}</h2><div class="detail-grid"><p><b>DNI</b><span>${e(x.dni)}</span></p><p><b>Celular</b><span>${e(x.phone)}</span></p><p><b>Correo</b><span>${e(x.email||'—')}</span></p><p><b>Especialidad</b><span>${e(programName(x.programId))}</span></p><p><b>Convocatoria</b><span>${e(x.cycle)}</span></p><p><b>Estado</b><span>${e(x.status)}</span></p><p class="field-wide"><b>Observaciones</b><span>${e(x.notes||'Sin observaciones')}</span></p></div>`)}
async function saveSettings(evt){evt.preventDefault();const f=evt.currentTarget,fd=new FormData(f),updated={...db.settings};if(settingTab==='paginas'){updated.pageText={...(updated.pageText||{})};PAGE_NAMES.forEach((name,i)=>{updated.pageText[name]={title:String(fd.get('page_title_'+i)||'').trim(),desc:String(fd.get('page_desc_'+i)||'').trim()}});const original=db.settings;db.settings=updated;if(persist('Encabezados de páginas actualizados.'))render();else db.settings=original;return;}for(const [key,_,type] of editableSettings[settingTab]){if(type==='image'){
 const upload=fd.get('upload_'+key);if(upload instanceof File&&upload.size){try{updated[key]=await fileToData(upload,'image')}catch(err){toast(err.message);return}}
 else {const value=String(fd.get(key)||'');if(value)updated[key]=value;}
 }else if(settingTab==='whatsapp'){updated.whatsapp={...(updated.whatsapp||{}),[key]:type==='check'?fd.has(key):String(fd.get(key)||'').trim()};}else if(settingTab==='comunidad'){updated.community={...(updated.community||{}),[key]:String(fd.get(key)||'').trim()};}else updated[key]=String(fd.get(key)||'').trim();}if(settingTab==='whatsapp'){const n=String(updated.whatsapp.number||'').replace(/\D/g,'');if(updated.whatsapp.enabled&&!/^9\d{8}$/.test(n)&&!/^519\d{8}$/.test(n)){toast('Escribe un celular de 9 dígitos que comience en 9 o 51 seguido de 9 dígitos.');return;}}const original=db.settings;db.settings=updated;if(persist('Contenido institucional actualizado.'))render();else db.settings=original;}
const EXPORT_KEYS=['settings','programs','news','gallery','documents','jobs','staffYears','teachers','directors','historyGallery','achievements','partners','offers','projects','calendarEvents','alumni','faqs','tours'];
function exportContent(){const payload={version:4,kind:'cetpro-public-content',exportedAt:new Date().toISOString(),content:Object.fromEntries(EXPORT_KEYS.map(key=>[key,db[key]]))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='respaldo_cetpro_contenidos_'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Respaldo de contenidos preparado.');}
function exportGithubContent(){
 const publicContent=Object.fromEntries(EXPORT_KEYS.map(key=>[key,db[key]]));
 const payload='/* Contenido PÚBLICO del CETPRO para GitHub Pages. No guardar datos personales aquí. */\nwindow.CETPRO_PUBLICADO = '+JSON.stringify(publicContent,null,2)+';\n';
 if(payload.length>12*1024*1024){toast('El archivo supera 12 MB. Reduce las imágenes antes de publicarlo.');return;}
 const blob=new Blob([payload],{type:'text/javascript;charset=utf-8'});
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='contenido-publicado.js';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
 toast('Archivo listo. Sustituye js/contenido-publicado.js en GitHub para publicar.');
}

async function importContent(ev){const file=ev.target.files?.[0];if(!file)return;
 if(file.size>15*1024*1024){toast('El respaldo JSON debe ocupar menos de 15 MB.');return;}
 try{const payload=JSON.parse(await file.text());if(!['cetpro-public-content','cetpro-demo-public-content'].includes(payload.kind)||!payload.content||!Array.isArray(payload.content.programs)){toast('El archivo no es un respaldo válido de esta demostración.');return;}
 if(!confirm('¿Importar esta copia? Sustituirá las publicaciones actuales. No se borrarán las solicitudes de matrícula ni las consultas.'))return;
 const updated={...db};for(const key of EXPORT_KEYS){const v=payload.content[key];if(key==='settings'){if(v&&typeof v==='object'&&!Array.isArray(v))updated.settings={...db.settings,...v};}else if(Array.isArray(v))updated[key]=v;}
 // Las especialidades permanecen limitadas a las cuatro con identificadores originales.
 updated.programs=defaults.programs.map(base=>({ ...base,...(updated.programs.find(x=>x.id===base.id)||{})}));updated.offers=defaults.offers.map(base=>({...base,...(updated.offers||[]).find(x=>x.programId===base.programId)}));
 const prev=db;db=updated;if(persist('Respaldo importado correctamente.'))render();else db=prev;
 }catch(err){toast('No se pudo leer el respaldo: '+err.message)}finally{ev.target.value='';}}
function bind(){
 document.querySelectorAll('[data-promote-event]').forEach(el=>el.addEventListener('click',()=>{const x=db.calendarEvents.find(a=>a.id===el.dataset.promoteEvent);if(!x)return;if(!confirm('¿Usar esta actividad como el anuncio emergente principal?'))return;db.settings.popup={...db.settings.popup,enabled:true,eyebrow:'ACTIVIDAD DESTACADA',title:x.title,body:x.description,image:x.image,button:'Ver agenda',destination:'#calendario',start:'',end:'',oncePerSession:true};persist('Evento vinculado con el anuncio emergente.');render()}));document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>{section=b.dataset.section;render()}));
 document.querySelector('#sideToggle')?.addEventListener('click',()=>document.querySelector('#aside')?.classList.toggle('side-open'));
 document.querySelector('#logout')?.addEventListener('click',()=>{window.CETPRO_AUTH.signOut().then(()=>{auth=false;section='dashboard';render()})});
 document.querySelector('#toggleSecurityPasswords')?.addEventListener('change',evt=>{document.querySelectorAll('#changePasswordForm input[type=password],#changePasswordForm input[type=text]').forEach(el=>el.type=evt.target.checked?'text':'password')});
 document.querySelector('#changePasswordForm')?.addEventListener('submit',async evt=>{
  evt.preventDefault();const form=evt.currentTarget,fd=new FormData(form),feedback=form.querySelector('#passwordFeedback'),button=form.querySelector('button[type=submit]');
  feedback.hidden=true;button.disabled=true;button.textContent='Actualizando…';
  try{await window.CETPRO_AUTH.updatePassword(String(fd.get('currentPassword')||''),String(fd.get('newPassword')||''),String(fd.get('repeatPassword')||''));form.reset();feedback.textContent='Contraseña actualizada correctamente. Usa la nueva contraseña al volver a iniciar sesión.';feedback.classList.add('success');feedback.hidden=false;toast('Contraseña actualizada correctamente.');}
  catch(err){feedback.textContent=err.message||'No se pudo actualizar la contraseña.';feedback.classList.remove('success');feedback.hidden=false;}
  finally{button.disabled=false;button.textContent='Guardar nueva contraseña';}
 });
 document.querySelector('#setAcademicYear')?.addEventListener('click',()=>{const value=document.querySelector('#academicYearActive')?.value;if(!value){toast('Primero crea una plana docente por año.');return;}db.settings.community={...(db.settings.community||{}),activeYear:Number(value)};persist('Año académico vigente actualizado.');render()});
 document.querySelector('#quickToggle')?.addEventListener('change',evt=>{db.settings.enrollmentOpen=evt.target.checked;persist('Estado de matrícula actualizado.');render()});
 document.querySelector('#enrollSettings')?.addEventListener('submit',evt=>{evt.preventDefault();const f=new FormData(evt.target);db.settings.enrollmentCycle=String(f.get('enrollmentCycle'));db.settings.enrollmentInfo=String(f.get('enrollmentInfo'));db.settings.enrollmentOpen=f.has('enrollmentOpen');persist('Configuración de matrícula guardada.');render()});
 document.querySelector('#popupImageSelect')?.addEventListener('change',evt=>{const img=document.querySelector('#popupImagePreview');if(img){img.src=picture(evt.target.value);img.dataset.fallback='assets/img/ilustracion-hero.svg';img.dataset.didFallback='';}const url=document.querySelector('#popupImageURL');if(url)url.value=/^https:/i.test(evt.target.value)?evt.target.value:''});
 document.querySelector('#popupImageURL')?.addEventListener('input',evt=>{if(/^https:\/\//i.test(evt.target.value.trim())){const img=document.querySelector('#popupImagePreview');if(img){img.src=evt.target.value.trim();img.dataset.didFallback='';}}});
 document.querySelector('#popupImageFile')?.addEventListener('change',evt=>{const file=evt.target.files?.[0];if(file){const img=document.querySelector('#popupImagePreview');if(img)img.src=URL.createObjectURL(file);}});
 document.querySelector('#popupForm')?.addEventListener('submit',async evt=>{evt.preventDefault();const el=evt.currentTarget,fd=new FormData(el),old=db.settings.popup||{},popup={...old};
 for(const key of ['eyebrow','title','body','button','destination','start','end'])popup[key]=String(fd.get(key)||'').trim();
 popup.enabled=fd.has('enabled');popup.oncePerSession=fd.has('oncePerSession');
 if(popup.start&&popup.end&&popup.end<popup.start){toast('La fecha final debe ser posterior a la fecha inicial.');return;}
 const uploaded=document.querySelector('#popupImageFile')?.files[0],url=document.querySelector('#popupImageURL')?.value.trim();
 if(uploaded){try{popup.image=await fileToData(uploaded,'image')}catch(err){toast(err.message);return;}}
 else if(url){if(!/^https:\/\//i.test(url)){toast('La dirección de la imagen debe usar HTTPS.');return;}popup.image=url;}
 else popup.image=document.querySelector('#popupImageSelect')?.value||old.image;
 const original=db.settings.popup;db.settings.popup=popup;
 if(persist('Anuncio emergente guardado.')){try{sessionStorage.removeItem('cetpro_popup_seen_bs5_v2')}catch{}render();}else db.settings.popup=original;
 });
 document.querySelector('#previewPopup')?.addEventListener('click',()=>{try{sessionStorage.removeItem('cetpro_popup_seen_bs5_v2')}catch{}window.open('index.html#inicio','_blank','noopener')});
 document.querySelector('#downloadCSV')?.addEventListener('click',csvExport);
 document.querySelectorAll('[data-status]').forEach(el=>el.addEventListener('change',evt=>{const x=db.enrollments.find(x=>x.id===evt.target.dataset.status);if(x){window.CETPRO_CLOUD.status(x.id,evt.target.value).then(()=>{toast('Estado de solicitud actualizado.');render()}).catch(err=>toast('Error al actualizar: '+err.message))}}));
 document.querySelectorAll('[data-detail]').forEach(el=>el.addEventListener('click',()=>{const x=db.enrollments.find(x=>x.id===el.dataset.detail);if(x)enrollmentDetails(x)}));
 document.querySelectorAll('[data-delete-enroll]').forEach(el=>el.addEventListener('click',()=>{if(confirm('¿Eliminar esta solicitud?')){window.CETPRO_CLOUD.deleteEnrollment(el.dataset.deleteEnroll).then(()=>{toast('Solicitud eliminada.');render()}).catch(err=>toast('Error: '+err.message))}}));
 document.querySelectorAll('[data-add]').forEach(el=>el.addEventListener('click',()=>recordModal(el.dataset.add,'')));
 document.querySelectorAll('[data-edit]').forEach(el=>el.addEventListener('click',()=>{const [key,id]=el.dataset.edit.split(':');recordModal(key,id)}));
 document.querySelectorAll('[data-toggle]').forEach(el=>el.addEventListener('click',()=>{const [key,id]=el.dataset.toggle.split(':'),x=db[key].find(x=>x.id===id);if(x){const col=schema[key].active;x[col]=!x[col];persist('Visibilidad actualizada.');render()}}));
 document.querySelectorAll('[data-delete]').forEach(el=>el.addEventListener('click',()=>{const [key,id]=el.dataset.delete.split(':');if(confirm('¿Eliminar esta publicación?')){db[key]=db[key].filter(x=>x.id!==id);persist('Publicación eliminada.');render()}}));
 document.querySelectorAll('[data-read]').forEach(el=>el.addEventListener('click',()=>{const x=db.messages.find(x=>x.id===el.dataset.read);if(x){window.CETPRO_CLOUD.markRead(x.id).then(()=>render()).catch(err=>toast('Error: '+err.message));openModal(`<div class="modal-eyebrow">CONSULTA RECIBIDA</div><h2>${e(x.subject)}</h2><p><b>Remitente:</b> ${e(x.full_name)} (${e(x.email)})</p><div class="message-body">${e(x.message).replace(/\n/g,'<br>')}</div>`);document.querySelectorAll('.side-links button').forEach(b=>{if(b.dataset.section==='messages')b.querySelector('small')?.remove()});}}));
 document.querySelectorAll('[data-delete-message]').forEach(el=>el.addEventListener('click',()=>{if(confirm('¿Eliminar este mensaje?')){window.CETPRO_CLOUD.deleteMessage(el.dataset.deleteMessage).then(()=>{toast('Mensaje eliminado.');render()}).catch(err=>toast('Error: '+err.message))}}));
 document.querySelectorAll('[data-settings-tab]').forEach(el=>el.addEventListener('click',()=>{settingTab=el.dataset.settingsTab;render()}));
 document.querySelector('#settingsForm')?.addEventListener('submit',saveSettings);
 
 document.querySelector('#exportContent')?.addEventListener('click',exportContent);
 document.querySelector('#importContent')?.addEventListener('change',importContent);
 document.querySelectorAll('[data-img-pick]').forEach(el=>el.addEventListener('change',()=>{const img=document.querySelector(`[data-preview="${el.dataset.imgPick}"]`);if(img)img.src=picture(el.value)}));
 document.querySelectorAll('[data-img-file]').forEach(el=>el.addEventListener('change',()=>{if(el.files[0]){const img=document.querySelector(`[data-preview="${el.dataset.imgFile}"]`);if(img)img.src=URL.createObjectURL(el.files[0])}}));
 
 document.querySelectorAll('[data-dismiss]').forEach(el=>el.addEventListener('click',closeModal));
 document.querySelector('#adminModal')?.addEventListener('click',evt=>{if(evt.target.id==='adminModal')closeModal()});
 document.querySelector('#adminModal')?.addEventListener('submit',ev=>{if(ev.target.id==='recordForm')saveForm(ev)});
 document.onkeydown=ev=>{if(ev.key==='Escape')closeModal()};}
function render(){refresh();auth=window.CETPRO_AUTH.sessionValid();if(!auth){login();document.title='Acceso administrador | CETPRO Huarmey';return}root.innerHTML=shell();bind();document.title=menus.find(x=>x[0]===section)?.[2]+' | Admin CETPRO';window.scrollTo(0,0)}
document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement){const img=ev.target;if(img.dataset.didFallback)return;img.dataset.didFallback='1';img.src=img.dataset.fallback||'assets/img/ilustracion-campus.svg'}},{capture:true});
(async()=>{
 const cloud=window.CETPRO_CLOUD;
 if(!cloud.configured){root.innerHTML='<main class="setup-notice"><h1>Falta conectar Supabase</h1><p>Configura <code>js/config.js</code> y ejecuta el SQL de la carpeta <code>database</code>. El panel no admite contraseñas de demostración.</p><a href="index.html">Volver al sitio</a></main>';return;}
 root.innerHTML='<main class="setup-notice"><h1>Conectando al administrador…</h1></main>';
 try{await cloud.loadPublic();await window.CETPRO_AUTH.restore();render();}
 catch(err){root.innerHTML='<main class="setup-notice"><h1>No se pudo conectar</h1><p>'+e(err.message)+'</p><p>Verifica Supabase y las políticas SQL.</p></main>';}
})();
